  const postId = Number.parseInt(id, 10)
  const post = {
    id: postId,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(
  request: Request,
  { params }: PostRouteContext
): Promise<Response> {
  const { id } = await params
  const update = await readPostUpdate(request)

  if (update instanceof Response) {
    return update
  }

  const post = {
    id: Number.parseInt(id, 10),
    title: update.title ?? `Post ${id}`,
    content: update.content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function DELETE(
  _request: Request,
  { params }: PostRouteContext
): Promise<Response> {
  const { id } = await params

  return Response.json({ message: `Post ${id} deleted successfully` })
}

