const API_URL = 'https://jsonplaceholder.typicode.com'

async function fetchJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, init)

  if (!response.ok) {
    throw new Error(`Failed to fetch ${url}: ${response.status}`)
  }

  return (await response.json()) as T
}

export function getRecentBlogPosts(): Promise<BlogPost[]> {
  return fetchJson<BlogPost[]>(`${API_URL}/posts?_limit=5`, {
    cache: 'no-store',
  })
}

export function getAllBlogPosts(): Promise<BlogPost[]> {
  return fetchJson<BlogPost[]>(`${API_URL}/posts`, { cache: 'no-store' })
}

export function getBlogPostsForListing(): Promise<BlogPost[]> {
  return fetchJson<BlogPost[]>(`${API_URL}/posts`, {
    next: { revalidate: 60 },
  })
}

export async function getBlogPost(id: string): Promise<BlogPost | null> {
  const response = await fetch(`${API_URL}/posts/${encodeURIComponent(id)}`, {
    next: { revalidate: 300 },
  })

  if (response.status === 404) {
    return null
  }

  if (!response.ok) {
    throw new Error(`Failed to fetch blog post ${id}: ${response.status}`)
  }

  return (await response.json()) as BlogPost
}

export function getBlogComments(id: string): Promise<BlogComment[]> {
  return fetchJson<BlogComment[]>(
    `${API_URL}/posts/${encodeURIComponent(id)}/comments`,
    { next: { revalidate: 300 } }
  )
}

